import sys

def fibonacci(n):
    if n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def main():
    n = int(sys.stdin.readline().strip())
    result = fibonacci(n)
    print(result)

if __name__ == "__main__":
    main()
